BEGIN;
SET LOCAL statement_timeout='5s'; SET LOCAL lock_timeout='500ms';
DO $reserve$
DECLARE job_started timestamptz:=clock_timestamp();
BEGIN
  IF NOT pg_try_advisory_xact_lock(hashtextextended('comparator_strict:atomic-v1',0))
    OR EXISTS(SELECT 1 FROM comparator_strict.execution_jobs WHERE status IN ('planned','running','halted','unknown'))
    OR EXISTS(SELECT 1 FROM comparator_strict.execution_jobs WHERE job_key='ce1-ce200-d9a6ae5c4267e5b61fedacb44b97') THEN RAISE EXCEPTION 'ce200_exclusive_or_replay'; END IF;
  IF EXISTS(SELECT 1 FROM pg_stat_activity WHERE cardinality(pg_blocking_pids(pid))>0
    OR (pid<>pg_backend_pid() AND state='active' AND query_start<clock_timestamp()-interval '30 seconds')) THEN RAISE EXCEPTION 'ce200_health_stop'; END IF;
  UPDATE comparator_strict.execution_budget SET
    sql_ms_reserved=sql_ms_reserved+10000,read_rows_reserved=read_rows_reserved+100,
    bytes_reserved=bytes_reserved+1048576,write_rows_reserved=write_rows_reserved+3,updated_at=clock_timestamp()
    WHERE project_ref='gkffvigcnsesbaihycay' AND budget_date=DATE '2026-09-03'
      AND approval_reference='CE-200-corpus-v1' AND bytes_limit=134217728 AND read_rows_limit=50000
      AND bytes_reserved+1048576<=bytes_limit AND read_rows_reserved+100<=read_rows_limit AND write_rows_reserved+3<=2000;
  IF NOT FOUND THEN RAISE EXCEPTION 'ce200_budget'; END IF;
  INSERT INTO comparator_strict.execution_jobs(id,project_ref,operation_key,sql_sha256,status,started_at,deadline_at,job_key,operation_hash,budget_date,reservation)
    VALUES(gen_random_uuid(),'gkffvigcnsesbaihycay','ce200-supplement','e6c42623ba02f860fe56d6f07e07b6db15194e3984a5b15896c19c367d0329a2','running',job_started,job_started+interval '20 minutes','ce1-ce200-d9a6ae5c4267e5b61fedacb44b97','d9a6ae5c4267e5b61fedacb44b973c64bdd808af24ad354b9179bd55e8269533',DATE '2026-09-03','{"sqlMs":10000,"readRows":100,"writeRows":3,"responseBytes":1048576}'::jsonb);
END $reserve$;
COMMIT;
BEGIN;
SET LOCAL statement_timeout='5s'; SET LOCAL lock_timeout='500ms';
DO $payload$
DECLARE payload jsonb; data jsonb; started timestamptz:=clock_timestamp();
BEGIN
  IF NOT pg_try_advisory_xact_lock(hashtextextended('comparator_strict:atomic-v1',0))
    OR NOT EXISTS(SELECT 1 FROM comparator_strict.execution_jobs WHERE job_key='ce1-ce200-d9a6ae5c4267e5b61fedacb44b97' AND status='running' AND operation_hash='d9a6ae5c4267e5b61fedacb44b973c64bdd808af24ad354b9179bd55e8269533' AND deadline_at>clock_timestamp()) THEN RAISE EXCEPTION 'ce200_lease'; END IF;
  SELECT coalesce(jsonb_agg(to_jsonb(q)),'[]'::jsonb) INTO data FROM (SELECT id,display_name,brand,packaging,ean,category_id,category_name,category_ids,unit_price,price_format,price_per_unit,price_per_unit_unit,available,published,synced_at,regions,regional_prices,promo_base_price,offer_zones,raw,md5(to_jsonb(p)::text) AS source_row_md5 FROM public.consum_products p WHERE (published IS TRUE AND (display_name ~* '(agua|aigua|water|yogu|yogh|iogur|patat|papat)' OR category_name ~* '(agua|aigua|water|yogu|yogh|iogur|patat|papat)|b[ií]fidus'))
      AND NOT (published IS TRUE AND (display_name ~* '(agua|aigua|water|yogu|yogh|iogur|patat|papat)' OR category_name ~* '(agua|aigua|water|yogu|yogh|iogur|patat|papat)'))
      AND id COLLATE "C" > '' COLLATE "C" ORDER BY id COLLATE "C" LIMIT 100) q;
  payload:=jsonb_build_object('job_key','ce1-ce200-d9a6ae5c4267e5b61fedacb44b97','operation_hash','d9a6ae5c4267e5b61fedacb44b973c64bdd808af24ad354b9179bd55e8269533',
    'project_ref','gkffvigcnsesbaihycay','captured_at',started,'kind','supplement','store','consum',
    'cursor','','rows',data,'row_count',jsonb_array_length(data),'elapsed_ms',extract(epoch FROM clock_timestamp()-started)*1000);
  IF jsonb_array_length(data)>100 OR octet_length(payload::text)>1040384 THEN RAISE EXCEPTION 'ce200_result_limit'; END IF;
  UPDATE comparator_strict.execution_jobs SET status='succeeded',finished_at=clock_timestamp(),
    receipt=jsonb_build_object('payload_sha256',encode(sha256(convert_to(payload::text,'UTF8')),'hex'),'row_count',jsonb_array_length(data),'payload_bytes',octet_length(payload::text),'elapsed_ms',payload->'elapsed_ms') WHERE job_key='ce1-ce200-d9a6ae5c4267e5b61fedacb44b97';
  PERFORM set_config('comparator_strict.ce200_response',payload::text,true);
END $payload$;
SELECT current_setting('comparator_strict.ce200_response')::jsonb AS evidence;
